SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, t.eventtype, COUNT(DISTINCT t.hadm_id) AS num_admissions, percent_rank() OVER (PARTITION BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, t.eventtype ORDER BY i.los) AS percentile_rank_los FROM patients p JOIN transfers t ON p.subject_id = t.subject_id JOIN icustays i ON t.hadm_id = i.stay_id WHERE p.subject_id = 83 AND p.gender = 'M' AND p.anchor_age BETWEEN 78 AND 88 AND t.eventtype = 'transfer' AND i.los <= 10 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, t.eventtype ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, t.eventtype;